output = {
  "cookbook": "The Ultimate Anabolic Cookbook",
  "author": "Greg Doucette",
  "year": 2020,
  "total_recipes": len(recipes),
  "categories": ["Breakfast","Sandwiches","Wraps","Dinners","Snacks","Desserts","Shakes"],
  "notes": "Macros are estimates per the author. Toppings/condiments excluded unless specified. 1 serving veggies = up to 100 cal; 1 serving fruit = up to 100 cal.",
  "recipes": recipes
}

os.makedirs(os.path.expanduser('~/output'), exist_ok=True)
filepath = os.path.expanduser('~/output/recipes_verified_macros.json')
with open(filepath, 'w') as f:
    json.dump(output, f, indent=2)

print(f"Total recipes: {len(recipes)}")
for cat in output['categories']:
    count = sum(1 for r in recipes if r['category'] == cat)
    print(f"  {cat}: {count}")
print(f"File size: {os.path.getsize(filepath)/1024:.1f} KB")